import{_ as h,o as t,c as i,a2 as c}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse('{"title":"Luật Đảm bảo Nhà ở","description":"","frontmatter":{},"headers":[],"relativePath":"vi/45-住房保障法.md","filePath":"vi/45-住房保障法.md","lastUpdated":null}'),g={name:"vi/45-住房保障法.md"};function a(u,n,o,l,r,p){return t(),i("div",null,[...n[0]||(n[0]=[c('<h1 id="luat-đam-bao-nha-o" tabindex="-1">Luật Đảm bảo Nhà ở <a class="header-anchor" href="#luat-đam-bao-nha-o" aria-label="Permalink to &quot;Luật Đảm bảo Nhà ở&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Dự án</th><th>Nội dung</th></tr></thead><tbody><tr><td>Số tài liệu</td><td>45</td></tr><tr><td>Mô-đun</td><td>Hệ thống pháp luật và khuôn khổ quản trị</td></tr><tr><td>Từ khóa cốt lõi</td><td>Quyền ở, nhà ở đảm bảo, quyền tài phán không gian, môi trường đáng ở, chống đầu cơ</td></tr></tbody></table><h2 id="_1-muc-đich-lap-phap-va-nguyen-tac-co-ban" tabindex="-1">1. Mục đích lập pháp và nguyên tắc cơ bản <a class="header-anchor" href="#_1-muc-đich-lap-phap-va-nguyen-tac-co-ban" aria-label="Permalink to &quot;1. Mục đích lập pháp và nguyên tắc cơ bản&quot;">​</a></h2><p>《Luật Đảm bảo Nhà ở》 là một trong năm luật pháp hỗ trợ của văn minh cộng sinh neo, nhằm đảm bảo quyền ở của mọi sự sống bên trong Hengyuanzhou, xây dựng hệ thống đảm bảo nhà ở công bằng và bền vững, tận dụng công nghệ quyền tài phán không gian để cung cấp không gian ở phù hợp cho mọi tộc, và ngăn chặn đầu cơ cũng như cướp đoạt trong lĩnh vực nhà ở.</p><p>Luật này thiết lập các nguyên tắc cơ bản sau:</p><table tabindex="0"><thead><tr><th>Nguyên tắc</th><th>Nội hàm</th></tr></thead><tbody><tr><td>Nguyên tắc đảm bảo nhà ở</td><td>Mỗi sự sống có quyền获得 không gian ở phù hợp, nhà nước và văn minh có nghĩa vụ đảm bảo nhu cầu ở cơ bản</td></tr><tr><td>Nguyên tắc ưu tiên phúc lợi công cộng</td><td>Nhà ở trước hết là nhu cầu thiết yếu của cuộc sống, không phải hàng hóa đầu cơ, nhà ở đảm bảo có thuộc tính phúc lợi công cộng</td></tr><tr><td>Nguyên tắc hiệu quả không gian</td><td>Tận dụng công nghệ quyền tài phán không gian để nâng cao hiệu quả sử dụng không gian và mở rộng không gian đáng ở</td></tr><tr><td>Nguyên tắc thích ứng liên tộc</td><td>Cung cấp không gian ở thích ứng với đặc điểm sinh lý và thói quen sống của các tộc khác nhau</td></tr><tr><td>Nguyên tắc môi trường đáng ở</td><td>Không gian ở phải có môi trường sinh thái tốt, hạ tầng cơ bản và dịch vụ công cộng</td></tr><tr><td>Nguyên tắc chống đầu cơ</td><td>Cấm đầu cơ với nhà ở làm đối tượng, ngăn chặn nhà ở trở thành công cụ cướp đoạt của cải</td></tr></tbody></table><h2 id="_2-đam-bao-phap-luat-ve-quyen-o" tabindex="-1">2. Đảm bảo pháp luật về quyền ở <a class="header-anchor" href="#_2-đam-bao-phap-luat-ve-quyen-o" aria-label="Permalink to &quot;2. Đảm bảo pháp luật về quyền ở&quot;">​</a></h2><p>Luật này quy định rõ ràng rằng quyền ở là quyền cơ bản được Hiến pháp Cộng sinh trao cho mỗi sự sống, cụ thể bao gồm:</p><ol><li><strong>Quyền ở cơ bản</strong>: Mỗi sự sống có quyền获得 không gian ở không thấp hơn tiêu chuẩn tối thiểu, và tiêu chuẩn tối thiểu được xác định theo kích thước cơ thể và nhu cầu sống của tộc.</li><li><strong>Quyền đề xuất nhà ở đảm bảo</strong>: Sự sống đủ điều kiện có quyền đề xuất nhà ở đảm bảo, và điều kiện đề xuất cũng như tiêu chuẩn phân bổ công khai, minh bạch.</li><li><strong>Quyền an toàn ở</strong>: Không gian ở phải đáp ứng tiêu chuẩn an toàn, và nhà nguy hiểm cũng như không gian không đáng ở không được cho thuê hoặc phân bổ.</li><li><strong>Quyền ổn định ở</strong>: Người ở nhà ở đảm bảo, nếu đủ điều kiện, được hưởng quyền ở ổn định và không được trục xuất một cách tùy tiện.</li><li><strong>Quyền môi trường ở</strong>: Người ở có quyền获得 không khí sạch, nguồn nước và môi trường xung quanh tốt, đồng thời có quyền khiếu nại về ô nhiễm môi trường.</li><li><strong>Quyền cải tạo nhà ở</strong>: Người ở có quyền thực hiện cải tạo hợp lý đối với không gian ở, với điều kiện không ảnh hưởng đến an toàn công trình và quyền lợi của người khác.</li></ol><h2 id="_3-he-thong-đam-bao-nha-o" tabindex="-1">3. Hệ thống đảm bảo nhà ở <a class="header-anchor" href="#_3-he-thong-đam-bao-nha-o" aria-label="Permalink to &quot;3. Hệ thống đảm bảo nhà ở&quot;">​</a></h2><p>Hệ thống đảm bảo nhà ở của văn minh cộng sinh neo được chia thành ba loại nhà ở, bao phủ các cấp độ nhu cầu khác nhau:</p><table tabindex="0"><thead><tr><th>Loại</th><th>Tên</th><th>Đối tượng đảm bảo</th><th>Phương pháp phân bổ</th><th>Tiền thuê/Giá</th></tr></thead><tbody><tr><td>Loại thứ nhất</td><td>Nhà ở thuê công cộng</td><td>Nhóm thu nhập thấp, người tu luyện sơ cấp, người nhập cư mới</td><td>Hệ thống đề xuất và xem xét, phân bổ theo hàng đợi</td><td>Tiền thuê thấp biểu tượng</td></tr><tr><td>Loại thứ hai</td><td>Nhà ở sở hữu chung</td><td>Nhóm thu nhập trung bình, người tu luyện cấp trung bình</td><td>Hệ thống đề xuất và xem xét, phân bổ xổ số</td><td>Dưới giá thị trường, sở hữu chung giữa cá nhân và nhà nước</td></tr><tr><td>Loại thứ ba</td><td>Nhà ở thương mại</td><td>Nhóm thu nhập cao, người tu luyện cao cấp</td><td>Giao dịch thị trường</td><td>Giá thị trường, chịu sự ràng buộc của quy định</td></tr></tbody></table><p>Ngoài ra, công nghệ gấp không gian được sử dụng để xây dựng &quot;Khu dân cư không gian gấp&quot;: bên trong không gian vật lý hạn chế, công nghệ gấp không gian mở rộng diện tích ở, cung cấp thêm không gian ở cho khu vực mật độ cao. Khu dân cư không gian gấp phải trải qua đánh giá an toàn để đảm bảo sự ổn định của không gian.</p><h2 id="_4-thich-ung-nha-o-lien-toc" tabindex="-1">4. Thích ứng nhà ở liên tộc <a class="header-anchor" href="#_4-thich-ung-nha-o-lien-toc" aria-label="Permalink to &quot;4. Thích ứng nhà ở liên tộc&quot;">​</a></h2><p>Đối với nhu cầu ở đặc biệt của các tộc khác nhau bên trong Hengyuanzhou, luật này thiết lập hệ thống thích ứng nhà ở liên tộc:</p><ul><li><strong>Tộc thủy sinh</strong>: Cung cấp không gian ở dưới nước hoặc nhà ở lưỡng cư nước-đất, được trang bị hệ thống tuần hoàn nước và bảo trì chất lượng nước.</li><li><strong>Tộc bay</strong>: Cung cấp không gian ở trên cao hoặc nhà ở có sân bay cất cánh và hạ cánh, được trang bị quản lý giao thông không khí.</li><li><strong>Sự sống năng lượng</strong>: Cung cấp không gian ở với nồng độ năng lượng phù hợp, được trang bị thiết bị ổn định năng lượng.</li><li><strong>Tộc khổng lồ</strong>: Cung cấp không gian ở quy mô lớn, với kết cấu công trình được gia cố đặc biệt.</li><li><strong>Tộc vi mô</strong>: Cung cấp khu dân cư vi mô, được trang bị kênh thay đổi tỷ lệ và cơ sở vật chất đặc biệt.</li></ul><p>Tiêu chuẩn thích ứng nhà ở liên tộc được ban hành chung bởi部门主管 nhà ở và đại diện của mỗi tộc, và được cập nhật định kỳ.</p><h2 id="_5-xay-dung-va-quan-ly-nha-o" tabindex="-1">5. Xây dựng và quản lý nhà ở <a class="header-anchor" href="#_5-xay-dung-va-quan-ly-nha-o" aria-label="Permalink to &quot;5. Xây dựng và quản lý nhà ở&quot;">​</a></h2><ul><li><strong>Quy hoạch xây dựng nhà ở</strong>: Nhà nước ban hành quy hoạch xây dựng nhà ở theo tình hình tăng trưởng dân số và nhập cư, đảm bảo sự cân bằng giữa cung và cầu nhà ở.</li><li><strong>Tiêu chuẩn xây dựng</strong>: Việc xây dựng nhà ở đảm bảo phải đáp ứng tiêu chuẩn an toàn, môi trường, đáng ở, và cấm giảm chất lượng xây dựng.</li><li><strong>Quản lý bất động sản</strong>: Khu dân cư thực hiện mô hình kết hợp quản lý tự trị và quản lý bất động sản chuyên nghiệp, và người ở có quyền tham gia vào các quyết định quản lý bất động sản.</li><li><strong>Bảo trì nhà ở</strong>: Việc bảo trì nhà ở đảm bảo là trách nhiệm của cơ quan quản lý nhà ở, và kinh phí bảo trì được chi từ tích lũy công cộng.</li><li><strong>Cơ chế thoát ra</strong>: Khi thu nhập hoặc trình độ tu luyện của người ở nhà ở đảm bảo vượt quá tiêu chuẩn đảm bảo, họ phải thoát ra khỏi nhà ở đảm bảo hoặc chuyển đổi thành nhà ở thương mại, và được给予 thời gian chuyển tiếp hợp lý.</li></ul><h2 id="_6-chong-đau-co-va-giam-sat" tabindex="-1">6. Chống đầu cơ và giám sát <a class="header-anchor" href="#_6-chong-đau-co-va-giam-sat" aria-label="Permalink to &quot;6. Chống đầu cơ và giám sát&quot;">​</a></h2><p>Để ngăn chặn đầu cơ và cướp đoạt trong lĩnh vực nhà ở, luật này thiết lập các biện pháp giám sát sau:</p><ol><li>Hạn chế số lượng nhà ở thương mại mà cá nhân có thể sở hữu, và thu thuế bất động sản lũy tiến đối với phần vượt quá hạn mức.</li><li>Cấm cho thuê lại và bán lại nhà ở đảm bảo, và người vi phạm sẽ bị thu hồi tư cách đảm bảo và lấy lại nhà ở.</li><li>Xây dựng hệ thống công khai thông tin giao dịch nhà ở, để ngăn chặn hoạt động hộp đen và thao túng giá.</li><li>Thực hiện quản lý tư cách và giám sát vốn đối với các nhà phát triển bất động sản, để ngăn chặn xây dựng không hoàn thành và gian lận.</li><li>Thiết lập cơ chế khiếu nại nhà ở và giải quyết tranh chấp, để đảm bảo quyền lợi hợp pháp của người ở.</li></ol><h2 id="_7-trach-nhiem-phap-ly" tabindex="-1">7. Trách nhiệm pháp lý <a class="header-anchor" href="#_7-trach-nhiem-phap-ly" aria-label="Permalink to &quot;7. Trách nhiệm pháp lý&quot;">​</a></h2><p>Các hành vi vi phạm quy định của luật này sẽ chịu trách nhiệm sau tùy theo mức độ nghiêm trọng của vi phạm:</p><ul><li>Phân bổ nhà ở đảm bảo vi phạm quy định, ra lệnh khắc phục và xử phạt người có trách nhiệm.</li><li>Cho thuê lại, bán lại nhà ở đảm bảo, thu hồi tư cách đảm bảo, lấy lại nhà ở và phạt tiền.</li><li>Nhà phát triển giảm chất lượng xây dựng, ra lệnh xây dựng lại và phạt tiền, trường hợp nghiêm trọng thì thu hồi tư cách.</li><li>Đầu cơ nhà ở, thu thuế đầu cơ cao và phạt tiền.</li><li>Cho thuê nhà nguy hiểm gây tổn hại cho người ở, chịu trách nhiệm bồi thường, trường hợp nghiêm trọng thì truy cứu trách nhiệm hình sự.</li></ul><h2 id="ket-luan" tabindex="-1">Kết luận <a class="header-anchor" href="#ket-luan" aria-label="Permalink to &quot;Kết luận&quot;">​</a></h2><p>《Luật Đảm bảo Nhà ở》 là sự thực hiện của khái niệm &quot;mọi người đều có con đường&quot; của văn minh cộng sinh neo trong lĩnh vực nhà ở. Bằng cách xây dựng hệ thống đảm bảo nhà ở được phân loại, tận dụng công nghệ quyền tài phán không gian để mở rộng không gian ở, thích ứng với nhu cầu ở liên tộc, và đàn áp đầu cơ nhà ở, nó đảm bảo mỗi sự sống đều có thể có một ngôi nhà an toàn, phù hợp, ổn định, và cung cấp đảm bảo an cư cho sự tiến bộ chung của mọi tộc.</p><h2 id="tai-lieu-lien-quan" tabindex="-1">Tài liệu liên quan <a class="header-anchor" href="#tai-lieu-lien-quan" aria-label="Permalink to &quot;Tài liệu liên quan&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Nguyên tắc chung Hiến pháp Cộng sinh)</li><li>39-住房与环境保障 (Đảm bảo Nhà ở và Môi trường)</li><li>13-空间法理调度体系详解 (Giải thích chi tiết Hệ thống Quyền tài phán Không gian)</li><li>46-环境保护法 (Luật Bảo vệ Môi trường)</li></ul>',29)])])}const b=h(g,[["render",a]]);export{m as __pageData,b as default};
